INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES (
  $LEGAL_fabfc33afdef95$doc_immigration_act_2049$LEGAL_fabfc33afdef95$,
  $LEGAL_fabfc33afdef95$Immigration Act, 2049 (1992)$LEGAL_fabfc33afdef95$,
  NULL,
  $LEGAL_fabfc33afdef95$act$LEGAL_fabfc33afdef95$,
  2049,
  1992,
  8,
  $LEGAL_fabfc33afdef95${"id":"doc_immigration_act_2049","title":"Immigration Act, 2049 (1992)","originalTitle":null,"documentType":"act","yearBs":2049,"yearAd":1992,"totalPages":8,"nodes":[{"tier":1,"nodeType":"preamble","identifier":"Preamble","title":"Introductory matter","content":"THE IMMIGRATION ACT, 2049 (1992)\nDate of Royal Seal and Publication\n17 kartik 2049 ( 2 November 1992)\nThe Amending Act\n1. The Immigration (First Amendment) Act, 2050 (1993) 2050.6.27\n2. The Act Amending Some Nepal Acts, 2053 (1996) 206 5.8.12\nAct No. 30 of the year 2049 (1992 )\nAn Act Made to Provide for Immigration\nPreamble: Whereas, it is expedient to regulate and control th e entry of the\nforeigners into Nepal, their stay therein and their departure there from, and to manage\nthe arrival and departure of the citizens of Nepal;\nNow, therefore be it enacted by Parliament in the 21st year of the reign of His Majesty\nthe King Birendra Bir Bikram Shah Dev.","children":[]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-1","title":"Main provisions","content":null,"children":[{"tier":2,"nodeType":"rule","identifier":"1","title":"Short Title and Commencement","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"This Act may be called \"Immigration\nAct, 2049 (1992).\"","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"This Act shall come into force immediately.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"2","title":"Definitions","content":"Unless the subject or the context otherwise requires, in this Act: -\n(a) \"Immigration\" means the process of entering of the foreigners into\nNepal, their stay presenting therein and their depart therefrom.\n(b) \"Foreigner\" means any person at that time, wh o is not a citizen of\nNepal.\n(c) \"Passport\" means a passport, travel document or permit to make a\nvisit, issued by the government of any country for visiting a foreign\ncountry, and this term also includes the laissez passé issued by the\nUnited Nations Organization.\n(d) \"Visa\" means a permit issued by the Government of Nepal to a\nforeigner for entering into and staying in Nepal.\n(e) \"Department\" means the Immigration Departm ent established by\nGovernment of Nepal to regulate the entry of foreig ners into Nepal,\ntheir stay therein and their departure therefrom, a nd to manage the\narrival and departure of the citizens of Nepal.\n(f) \"Office\" means the Immigration Office under the Department.\n(g) \"Director General\" means the Head of the Department.\n(h) \"Immigration Officer\" means the Officer in ser vice in the Department\nand the Office, and it also includes the In charge of the Office.\n(i) \"Trekking\" means a journey to be made by a f oreigner on foot with\nnight haltage and it also includes a journey on foo t by a foreigner\nupto the base camp of the Himalaya range.\n(j) \"Prescribed\" or \"as prescribed\" means prescrib ed or as prescribed in\nthis Act or in the Rules framed hereunder.\n3.\nProvisions relating to entry, stay and departure : (1) No foreigner shall\nbe entitled to enter into and stay in Nepal without holding a /boxxbldpassport and a\nvisa.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The category, fees and other provisions relati ng to visas shall be as\nprescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A foreigner intending to trek in the prescrib ed area of Nepal has to\nobtain, in addition to a visa, the permit as prescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Fees for trekking and other provisions relati ng thereto shall be as\nprescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The point of entry into Nepal departure theref rom by a foreigners\nshall be as prescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"The provisions relating to departure from Nepal or entry into Nepal\nand departure therefrom of a citizen of Nepal shall be as prescribed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"4","title":"Conditions to be followed by a foreigner","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The terms to be followed\nby a foreigner staying in Nepal shall be as prescribed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The conditions to be followed by an agency providing service to a\nforeigner for a visa and trekking shall be as prescribed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"5","title":"Prohibition on the use of a fake passport or visa","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No one shall lie\nhis/her name, age, nationality or any other detail or make a false statement or use, or\ncause to be used a fake passport or visa.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No one shall enter into, stay in and depart fr om Nepal by submitting\nfake passport or visa.\n/boxxbld(3) No one shall cause any foreigner who does not hold a passport and a\nvisa issued by the government of a foreign country or by the official authorized\nby such government to enter into stay there in and depart there from.\n/boxxbld Inserted by the First Amendment\n/boxxbld Inserted by the First Amendment","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"6","title":"Power to examine and take into possession of docume nt","content":"The\nImmigration Officer or any employee designated by t he Director General may, at\nany time and in any place, examine the documents related with the entry, stay and\ndeparture of a foreigner and may take the documents pertaining thereto into his\nown possession.","children":[]},{"tier":2,"nodeType":"rule","identifier":"7","title":"Functions, duties and powers of the Director Genera l","content":"The Functions,\nduties and powers of the Director General shall be as follows :","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"To regulate, manage and control the entry of a foreigners their stay\nthere in and departure there from or cause to the same","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"To provide permit to the foreigners trekking.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"To issue visa as prescribed and extend the validity thereof.\n/boxxbld(c1) To cancel the trekking permit issued under cla use (b) or the visa\ngranted or extended under clause (c) in the prescribed circumstances.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"To manage the arrival and departure of the citizens of Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"To carry out or cause to be carried out the o ther functions in\naccordance with the directions given by Government of Nepal from\ntime to time.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"8","title":"Investigation of crime relating to immigration","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"♣(I) In a case where the\nDepartment or Office comes to be directly or indire ctly informed that any crime\nhas been committed or is likely to be committed con trary to this Act or the Rules\nframed hereunder, the Immigration Officer designate d by the Director General\nshall c on duc t investigation and initiate the procee ding of, the crime pertaining\nthereto.\n/boxxbld Inserted by the First Amendment","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While investigating the crime referred to in Sub s ection (1) or\ncollecting evidence or proofs, the Immigration Officer shall have all such powers\nas so conferred on to the police under the prevaili ng law, including the powers to\narrest the person involved in the crime, to search any place in regard to the crime,\nto take into control of the document or other mater ials concerned with the crime,\nand to prepare a deed of public inquiry (Sarjamin ) as well. IN the course of\ninvestigation, the Immigration Officer ♣may take statement of the accused, and\nrelease him/her un date ail or guarantee based on r easonable grounds or /handbckptrightdetain\nhim/her for a term not exceeding twenty five days, upon obtaining permission of\nthe Court.\nProvided, the Immigration Officer shall immediately inform the Director\nGeneral as he/she begins the investigation of the crime.\n/boxxbld(2a) In cases the accused fails to furnish bail or guranttee under Sub\nsection (2), he/she may be detained.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"While conducting on investigation pursuant to Sub section (2),\nthe Immigration Officer may, it necessary, consult with the Government\nAttorney.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"9","title":"Power to expel","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Director General, on the basis of the rep ort receiv ed\nf ro m the Immigration Officer after having completed the investigation of the crime\npursuant to this Act, may (in the case of a foreign er) and upon regulating the\nmatters required to be regulated as prescribed, and with the approval of\nGovernment of Nepal, expel such a foreigner from Ne pal, by disqualifying the\nforeigner from re entering into Nepal, with or without prescribing the period of\ntime.\n♣ Amended by the First Amendment\n/handbckptright The Act Amending Some Nepal Acts, 2053 (1996)\n/boxxbld Inserted by the First Amendment\n/boxxbld (1a) The Director General may, upon obtaining the approval of\nGovernment of Nepal, issue order requiring the expulsion of a foreigner who has\nundergone punishment for the commission of the acts contrary to this Act or the\nRules framed hereunder or the prevailing laws, from Nepal, with or without\nprescribing the period of time.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The foreigner expelled under ♣ Sub sections (1) and (1a) shall\nnot be entitled to re-enter into Nepal during the period of expulsion.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Other provisions relating to expulsion sha ll be as prescribed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"10","title":"Punishment","content":"( 1) Any person who commits, or causes to be commit ted, the\ncrime referred to in Section-5 shall be punished wi th a fine not exceeding fifty\nthousand rupees or imprisonment for a term not exce eding five years or with\nboth.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Any person who violates, or causes to be v iolated, Sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"of Section 9 shall, for the first time, be puni shed with a fine not exceeding\ntwenty five thousand rupees or imprisonment not exc eeding two years, or in\ncases where such person repeats the violations thereof, he shall be punished with\na fine of up to fifty thousand rupees or with impri sonment for a term not\nexceeding five years or with both, for each violation.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any accomplice of the crime carrying punis hment referred to\nin Sub-section (1) or (2) shall be punished with ha lf the punishment to be\nimposed on the offender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Except for the matters laid down in the Su b-sections above, a\nperson who commits any act in contravention of this Act or the Rules framed\n/boxxbld Inserted by the First Amendment\n♣ Amended by the First Amendment\nhereunder may be awarded by the Director General a fine of ♣up to fifty\nthousand rupees , and /boxxbldthe amount in question held to be payable by such p erson\nshall also be realized from such person .","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"11","title":"Appeal","content":"A party who is not satisfied with the punishment imposed pursuant to\nsub section (4) of Section 10 may file an appeal in the Appellate Court within 35\ndays.","children":[]},{"tier":2,"nodeType":"rule","identifier":"12","title":"Government of Nepal to be plaintiff","content":"In the cases under this Act,\nGovernment of Nepal shall be plaintiff.\n♣♣ ♣♣13. Exemption from visa fees : Any foreigner, who has been detained in the\ncourse of investigation under this Act or the preva iling laws, shall be exempted\nfrom the visa fees for the period of his detention and any foreigner against whom\na case has been filed shall be exempted from the vi sa fees for the period,\ncommencing from the day of filing the case against him up to that of the delivery\nof judgment of and in case of the imposition of pun ishment of imprisonment on\nhim, up to the day of completion of imprisonment, a nd in case of imposition of a\nfine only, up to the day of the payment of the fine.","children":[]},{"tier":2,"nodeType":"rule","identifier":"14","title":"Power of Government of Nepal","content":"( 1) Government of Nepal may make\nprovision for exempting the foreigner of any class, tribe or caste or nationality\nfrom the application of all or any of the provisions of this Act or the Rules\nframed hereunder, or for the application of only the prescribed terms to such\nforeigner.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Government of Nepal it thinks so appropria te that any\nforeigner's entry into, stay in or departure from N epal may be detrimental to the\n♣ Amended by the First Amendment\n/boxxbld Inserted by the First Amendment\n♣ Amended by the First Amendment\nnational interest, may prohibit the entry, stay or departure of such foreigner.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"15","title":"Power may be delegated","content":"The Director General may delegate any or all of the\npowers conferred on him under this Act to other officer or staff under him.","children":[]},{"tier":2,"nodeType":"rule","identifier":"16","title":"Institution of proceedings under other prevailing law not Prohibited","content":"No matter set forth in this Act shall be deemed to bar the institution of a case\nagainst any person in the court under other Prevailing law.","children":[]},{"tier":2,"nodeType":"rule","identifier":"17","title":"Protection of action in good faith","content":"No claim of or institution of prosecution\nor any other legal proceedings shall be made against any staff for anything done\nor intended to be done in good faith under this Act.","children":[]},{"tier":2,"nodeType":"rule","identifier":"18","title":"Power to frame Rules","content":"Government of Nepal may frame Rules to fulfill\naccomplish the objective of this Act.","children":[]},{"tier":2,"nodeType":"rule","identifier":"19","title":"Repeal and saying","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Foreigners Act, 2015 (1958) is hereby repealed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The acts done or actions taken under the Fore igners Act, 2015 (1958) and\nthe Rules framed thereunder shall be deemed to have been done or taken under\nthis Act.","children":[]}]}]}]}$LEGAL_fabfc33afdef95$::jsonb
)
